void clearDrum(int b){for(auto&r:drums[b])r.fill(false);} void clearNote(NoteClip&c){for(auto&r:c)r.fill(false);} void clearCell(int t,int b){if(b<0||b>=activeBars)return;if(t==0)clearDrum(b);else clearNote(t==1?bass[b]:melody[b]);} bool usedDrum(int b){for(auto&r:drums[b])for(bool x:r)if(x)return true;return false;} bool usedNote(const NoteClip&c){for(auto&r:c)for(bool x:r)if(x)return true;return false;}
void clampScroll(){scrollBar=std::clamp(scrollBar,0,std::max(0,activeBars-visibleBars));} void ensureVisible(int b){if(b<scrollBar)scrollBar=b;if(b>=scrollBar+visibleBars)scrollBar=b-visibleBars+1;clampScroll();}
